package com.taobao.arthas.core.util.collection;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Regression test for off-by-one error in ThreadUnsafeFixGaStack.checkForPush().
 *
 * The checkForPush() guard uses "current == max" but current starts at -1 and is
 * pre-incremented before use. After max successful pushes, current == max-1.
 * The guard should trigger when current >= max-1 (stack is full), not when
 * current == max (which is unreachable before the array bounds check fires).
 *
 * Correct behavior: when the stack is full, checkForPush() should throw
 * ArrayIndexOutOfBoundsException with no message, BEFORE the array access.
 * Buggy behavior: the guard never triggers, and the JVM's array bounds check
 * throws ArrayIndexOutOfBoundsException with a message like
 * "Index X out of bounds for length Y".
 */
class ThreadUnsafeFixGaStackTest {

    @Test
    void pushBeyondCapacity_shouldThrowFromGuardNotFromArrayAccess() {
        int max = 5;
        ThreadUnsafeFixGaStack<String> stack = new ThreadUnsafeFixGaStack<>(max);

        // Fill the stack to capacity (max pushes should succeed)
        for (int i = 0; i < max; i++) {
            stack.push("element-" + i);
        }

        // Stack is now full. The next push should be rejected by checkForPush(),
        // NOT by the JVM's array bounds check.
        ArrayIndexOutOfBoundsException ex = assertThrows(
                ArrayIndexOutOfBoundsException.class,
                () -> stack.push("overflow")
        );

        // If checkForPush() catches it, the message is empty (default constructor).
        // If the array access catches it, the message is non-empty
        // ("Index 5 out of bounds for length 5").
        // The guard should be the one throwing, so the message must be empty/null.
        assertNull(ex.getMessage(),
                "checkForPush() should reject the push before array access; "
                + "exception should come from the guard, not from the JVM bounds check. "
                + "Got message: " + ex.getMessage());
    }

    @Test
    void pushExactlyMaxElements_shouldSucceed() {
        int max = 5;
        ThreadUnsafeFixGaStack<String> stack = new ThreadUnsafeFixGaStack<>(max);

        for (int i = 0; i < max; i++) {
            stack.push("element-" + i);
        }

        // All max elements should be present and retrievable in LIFO order
        for (int i = max - 1; i >= 0; i--) {
            assertEquals("element-" + i, stack.pop());
        }
        assertTrue(stack.isEmpty());
    }

    @Test
    void smallStack_shouldRejectOverflowCorrectly() {
        // Use a very small stack to make the off-by-one visible
        ThreadUnsafeFixGaStack<String> stack = new ThreadUnsafeFixGaStack<>(1);

        // Push 1 element (max capacity) should work
        stack.push("one");

        // Push 2nd element should fail from checkForPush() guard
        ArrayIndexOutOfBoundsException ex = assertThrows(
                ArrayIndexOutOfBoundsException.class,
                () -> stack.push("two")
        );

        assertNull(ex.getMessage(),
                "Guard should throw before array access; message should be null. "
                + "Got: " + ex.getMessage());
    }
}

