package com.taobao.arthas.core.shell.system.impl;

import com.taobao.arthas.core.shell.system.Job;
import org.junit.Test;
import org.mockito.Mockito;

import java.lang.reflect.Constructor;

import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * Test for JobTimeoutTask to verify that the catch block properly logs job info
 * when terminate() throws an exception.
 *
 * Bug: In JobTimeoutTask.run(), line 119 sets `job = null`, then the catch block
 * at line 124 tries to access `job.id()` and `job.line()`. Since job was already
 * set to null on line 119, this causes NullPointerException in the catch block,
 * and the error logging never happens (NPE is silently swallowed by inner catch).
 *
 * Correct behavior: the catch block should use the `temp` variable (which holds
 * the job reference before nullification) so that job.id() and job.line() can
 * be called successfully for logging.
 */
public class JobTimeoutTaskTest {

    /**
     * Test that when job.terminate() throws, the catch block should still be able
     * to call job.id() and job.line() for error logging.
     *
     * The bug prevents these calls because `job` is nullified before the catch block.
     * After the fix, `temp` should be used instead of `job` in the catch block.
     *
     * This test asserts the CORRECT behavior: when terminate() throws, the catch
     * block should successfully call id() and line() on the job for logging.
     */
    @Test
    public void testRunShouldLogJobInfoWhenTerminateThrows() throws Exception {
        // Create a mock Job whose terminate() throws an exception
        Job mockJob = Mockito.mock(Job.class);
        Mockito.when(mockJob.id()).thenReturn(42);
        Mockito.when(mockJob.line()).thenReturn("test command");
        Mockito.doThrow(new RuntimeException("terminate failure")).when(mockJob).terminate();

        // Access the private static inner class JobTimeoutTask via reflection
        Class<?> clazz = GlobalJobControllerImpl.class;
        Class<?>[] innerClasses = clazz.getDeclaredClasses();
        Class<?> jobTimeoutTaskClass = null;
        for (Class<?> inner : innerClasses) {
            if (inner.getSimpleName().equals("JobTimeoutTask")) {
                jobTimeoutTaskClass = inner;
                break;
            }
        }
        if (jobTimeoutTaskClass == null) {
            throw new AssertionError("JobTimeoutTask inner class not found");
        }

        // Create an instance of JobTimeoutTask via reflection
        Constructor<?> constructor = jobTimeoutTaskClass.getDeclaredConstructor(Job.class);
        constructor.setAccessible(true);
        Runnable task = (Runnable) constructor.newInstance(mockJob);

        // Execute run() - this will call terminate() which throws,
        // then the catch block should call job.id() and job.line()
        task.run();

        // Verify that id() was called in the catch block for logging.
        // This is the correct behavior: even when terminate() fails,
        // the catch block should log the job info.
        // BUG: currently this fails because job is null in the catch block,
        // causing NPE which is silently swallowed, so id() is never called.
        verify(mockJob, times(1)).id();
        verify(mockJob, times(1)).line();
    }
}

