package com.alibaba.arthas.tunnel.server.cluster;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.util.Map;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito;
import org.springframework.data.redis.core.RedisOperations;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.ValueOperations;

/**
 * Tests for RedisTunnelClusterStore.
 */
public class RedisTunnelClusterStoreTest {

    @Test
    public void testAgentInfoWhenKeysReturnsNullShouldNotThrowNPE() {
        // Create the store
        RedisTunnelClusterStore store = new RedisTunnelClusterStore();

        // Mock the StringRedisTemplate
        StringRedisTemplate redisTemplate = Mockito.mock(StringRedisTemplate.class);

        // Mock ValueOperations
        ValueOperations<String, String> valueOps = Mockito.mock(ValueOperations.class);

        // Mock RedisOperations (returned by getOperations())
        RedisOperations<String, String> redisOps = Mockito.mock(RedisOperations.class);

        // Set up the chain: redisTemplate.opsForValue() -> valueOps
        when(redisTemplate.opsForValue()).thenReturn(valueOps);

        // valueOps.getOperations() -> redisOps
