package com.taobao.arthas.core.shell.term.impl.http;

import com.taobao.arthas.core.security.BasicPrincipal;
import io.netty.handler.codec.http.DefaultHttpHeaders;
import io.netty.handler.codec.http.HttpHeaders;
import io.netty.handler.codec.http.HttpRequest;
import org.junit.Test;

import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

import static org.junit.Assert.*;

/**
 * Test that HTTP Basic Auth credentials are decoded using UTF-8 charset
 * as required by RFC 7617, not the platform default charset.
 * 
 * When run with -Dfile.encoding=ISO-8859-1 (via -DargLine), Charset.defaultCharset()
 * returns ISO-8859-1, which would incorrectly decode UTF-8 credential bytes.
 * 
 * Run: mvn test -Dtest=BasicHttpAuthenticatorHandlerCharsetTest -pl core -DargLine="-Dfile.encoding=ISO-8859-1"
 */
public class BasicHttpAuthenticatorHandlerCharsetTest {

    /**
     * Test that non-ASCII credentials encoded in UTF-8 are correctly decoded.
     * 
     * The HTTP client sends credentials as: username:password UTF-8 encoded, then Base64 encoded.
     * Per RFC 7617, the credentials in the Authorization header must be decoded as UTF-8.
     * 
     * When run with -DargLine="-Dfile.encoding=ISO-8859-1", the buggy code
     * (using Charset.defaultCharset()) will decode the UTF-8 bytes as ISO-8859-1,
     * producing garbled credentials.
     */
    @Test
    public void testNonAsciiCredentialsDecodedWithUtf8() throws Exception {
        // Create mock HttpRequest with non-ASCII credentials
        String username = "测试用户"; // Chinese characters
        String password = "密码123"; // Chinese characters + digits
        String credentials = username + ":" + password;

        // Encode credentials as UTF-8 bytes, then Base64 encode (as the HTTP client would)
        byte[] utf8Bytes = credentials.getBytes(StandardCharsets.UTF_8);
        String base64Credentials = Base64.getEncoder().encodeToString(utf8Bytes);

        // Create mock HTTP headers with Basic Auth
        HttpHeaders headers = new DefaultHttpHeaders();
        headers.add("Authorization", "Basic " + base64Credentials);

        HttpRequest mockRequest = createMockRequest(headers);

        // Call the static method via reflection (it's protected static, no instance needed)
        Method method = BasicHttpAuthenticatorHandler.class
                .getDeclaredMethod("extractBasicAuthSubject", io.netty.handler.codec.http.HttpRequest.class);
        method.setAccessible(true);

        BasicPrincipal result = (BasicPrincipal) method.invoke(null, mockRequest);

        assertNotNull("Should extract a principal from valid Basic Auth header", result);
        assertEquals("Username should be decoded as UTF-8", username, result.getUsername());
        assertEquals("Password should be decoded as UTF-8", password, result.getPassword());
    }

    /**
     * Test with a mix of ASCII and non-ASCII characters.
     */
    @Test
    public void testMixedAsciiNonAsciiCredentials() throws Exception {
        String username = "user_日本語";
        String password = "pässwörd_测试";
        String credentials = username + ":" + password;

        byte[] utf8Bytes = credentials.getBytes(StandardCharsets.UTF_8);
        String base64Credentials = Base64.getEncoder().encodeToString(utf8Bytes);

        HttpHeaders headers = new DefaultHttpHeaders();
        headers.add("Authorization", "Basic " + base64Credentials);

        HttpRequest mockRequest = createMockRequest(headers);

        Method method = BasicHttpAuthenticatorHandler.class
                .getDeclaredMethod("extractBasicAuthSubject", io.netty.handler.codec.http.HttpRequest.class);
        method.setAccessible(true);

        BasicPrincipal result = (BasicPrincipal) method.invoke(null, mockRequest);

        assertNotNull(result);
        assertEquals("Username should be correctly decoded", username, result.getUsername());
        assertEquals("Password should be correctly decoded", password, result.getPassword());
    }

    /**
     * Test that ASCII-only credentials work (baseline sanity check).
     */
    @Test
    public void testAsciiOnlyCredentials() throws Exception {
        String username = "admin";
        String password = "secret";
        String credentials = username + ":" + password;

        byte[] utf8Bytes = credentials.getBytes(StandardCharsets.UTF_8);
        String base64Credentials = Base64.getEncoder().encodeToString(utf8Bytes);

        HttpHeaders headers = new DefaultHttpHeaders();
        headers.add("Authorization", "Basic " + base64Credentials);

        HttpRequest mockRequest = createMockRequest(headers);

        Method method = BasicHttpAuthenticatorHandler.class
                .getDeclaredMethod("extractBasicAuthSubject", io.netty.handler.codec.http.HttpRequest.class);
        method.setAccessible(true);

        BasicPrincipal result = (BasicPrincipal) method.invoke(null, mockRequest);

        assertNotNull(result);
        assertEquals("ASCII username", username, result.getUsername());
        assertEquals("ASCII password", password, result.getPassword());
    }

    /**
     * Create a simple HttpRequest that returns the given headers.
     */
    private HttpRequest createMockRequest(HttpHeaders headers) {
        return new io.netty.handler.codec.http.DefaultHttpRequest(
                io.netty.handler.codec.http.HttpVersion.HTTP_1_1,
                io.netty.handler.codec.http.HttpMethod.GET,
                "/") {
            private final HttpHeaders myHeaders = headers;
            @Override
            public HttpHeaders headers() {
                return myHeaders;
            }
        };
    }
}

