package com.alibaba.arthas.tunnel.server;

import java.util.concurrent.atomic.AtomicInteger;

import org.assertj.core.api.Assertions;
import org.junit.Test;
import org.mockito.Mockito;

import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelPromise;
import io.netty.channel.DefaultChannelPromise;
import io.netty.channel.embedded.EmbeddedChannel;
import io.netty.util.ReferenceCounted;

/**
 * Tests for RelayHandler.
 */
public class RelayHandlerTest {

    /**
     * When RelayHandler forwards a message to the relay channel, it must
     * call retain() first so that the message is not prematurely released
     * by the original channel's pipeline after channelRead returns.
     *
     * Without retain(), the original pipeline releases the message (refCnt
     * goes from 1 to 0), and the relay channel receives a deallocated buffer.
     */
    @Test
    public void channelReadShouldRetainMessageBeforeForwarding() {
        AtomicInteger capturedRefCnt = new AtomicInteger(-1);

        // Create a mock relay channel that is active
        Channel relayChannel = Mockito.mock(Channel.class);
        Mockito.when(relayChannel.isActive()).thenReturn(true);
        Mockito.when(relayChannel.writeAndFlush(Mockito.any()))
                .thenAnswer(inv -> {
                    Object msg = inv.getArgument(0);
                    if (msg instanceof ReferenceCounted) {
                        capturedRefCnt.set(((ReferenceCounted) msg).refCnt());
                    }
                    return new DefaultChannelPromise(relayChannel);
                });

        RelayHandler handler = new RelayHandler(relayChannel);

        // Create a reference-counted message with initial refCnt = 1
        ByteBuf buf = Unpooled.buffer().writeBytes("test".getBytes());
        Assertions.assertThat(buf.refCnt()).isEqualTo(1);

        // Write the message through the embedded channel, which will invoke
        // RelayHandler.channelRead()
        EmbeddedChannel channel = new EmbeddedChannel(handler);
        channel.writeInbound(buf);

        // The relayChannel.writeAndFlush should have been called with a retained
        // message (refCnt = 2: 1 original + 1 from retain()).
        // With the bug (no retain()), refCnt would be 1.
        Assertions.assertThat(capturedRefCnt.get())
                .as("message should be retained before forwarding to relay channel")
                .isEqualTo(2);
    }

    /**
     * When relayChannel is not active, the message should be released
     * immediately (not forwarded). This verifies the else branch.
     */
    @Test
    public void channelReadShouldReleaseMessageWhenRelayChannelInactive() {
        Channel relayChannel = Mockito.mock(Channel.class);
        Mockito.when(relayChannel.isActive()).thenReturn(false);

        RelayHandler handler = new RelayHandler(relayChannel);

        ByteBuf buf = Unpooled.buffer().writeBytes("test".getBytes());
        Assertions.assertThat(buf.refCnt()).isEqualTo(1);

        EmbeddedChannel channel = new EmbeddedChannel(handler);
        channel.writeInbound(buf);

        // After the handler releases the message, refCnt should be 0
        Assertions.assertThat(buf.refCnt()).isEqualTo(0);
    }
}

