package com.taobao.arthas.grpcweb.proxy;

import io.netty.channel.Channel;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelFutureListener;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelPromise;
import io.netty.handler.codec.http.FullHttpRequest;
import io.netty.handler.codec.http.HttpHeaderNames;
import io.netty.handler.codec.http.HttpMethod;
import io.netty.handler.codec.http.HttpVersion;
import io.netty.handler.codec.http.DefaultFullHttpRequest;
import io.netty.handler.codec.http.DefaultHttpHeaders;
import io.netty.buffer.Unpooled;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Tests for SendGrpcWebResponse, including the race condition in writeResponse().
 *
 * BUG: In writeResponse(), isSuccessSendData is returned synchronously but set
 * asynchronously in the ChannelFutureListener callback. Since ctx.writeAndFlush()
 * is asynchronous, the callback hasn't executed yet when "return isSuccessSendData"
 * runs. This means the method always returns the result of the PREVIOUS write
 * operation, not the current one. On first call, it always returns true (default
 * value).
 */
public class SendGrpcWebResponseTest {

    /**
     * Test that writeResponse returns the current write's result, not the previous write's stale value.
     *
     * The bug: isSuccessSendData is only ever set to false (in the async failure listener).
     * It is never reset to true at the start of a new write. So after one failure,
     * ALL subsequent calls return false, even if the current write succeeds.
     */
    @Test
    public void testWriteResponseDoesNotReturnStalePreviousFailure() throws Exception {
        // Setup mocks
        ChannelHandlerContext ctx = mock(ChannelHandlerContext.class);
        Channel channel = mock(Channel.class);
        when(ctx.channel()).thenReturn(channel);

        // Create a latch-based future so we control when the async callback fires
        CountDownLatch latch1 = new CountDownLatch(1);
        ChannelFuture future1 = mock(ChannelFuture.class);
        when(future1.isSuccess()).thenReturn(true);
        when(future1.sync()).thenReturn(future1);
        doAnswer(invocation -> {
            ChannelFutureListener listener = invocation.getArgument(0);
            // Don't fire the listener yet — it's async
            return null;
        }).when(future1).addListener(any(ChannelFutureListener.class));
        when(channel.newPromise()).thenReturn(mock(ChannelPromise.class));
        when(ctx.writeAndFlush(any())).thenReturn(future1);

        // Create a second future for the second call
        CountDownLatch latch2 = new CountDownLatch(1);
        ChannelFuture future2 = mock(ChannelFuture.class);
        when(future2.isSuccess()).thenReturn(true);
        when(future2.sync()).thenReturn(future2);
        doAnswer(invocation -> {
            ChannelFutureListener listener = invocation.getArgument(0);
            // Don't fire the listener yet — it's async
            return null;
        }).when(future2).addListener(any(ChannelFutureListener.class));

        // Create request with grpc-web-text content type
        DefaultHttpHeaders headers = new DefaultHttpHeaders();
        headers.set(HttpHeaderNames.CONTENT_TYPE, "application/grpc-web-text");
        FullHttpRequest request = new DefaultFullHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.POST, "/test", Unpooled.EMPTY_BUFFER, headers, DefaultHttpHeaders.EMPTY_HEADERS);

        SendGrpcWebResponse response = new SendGrpcWebResponse(ctx, request);

        // ---- First write: returns true (default value) ----
        boolean result1 = response.writeResponse(new byte[]{1, 2, 3});

        // This is the BUG: result1 should reflect the first write's outcome.
        // But since the async callback hasn't fired yet, it returns the DEFAULT (true).
        // If the first write actually fails, we should know about it, but we don't.

        // Now simulate the FIRST write FAILING asynchronously
        ArgumentCaptor<ChannelFutureListener> listenerCaptor1 = ArgumentCaptor.forClass(ChannelFutureListener.class);
        verify(future1).addListener(listenerCaptor1.capture());
        ChannelFutureListener capturedListener1 = listenerCaptor1.getValue();
        // Simulate failure
        ChannelFuture failedFuture = mock(ChannelFuture.class);
        when(failedFuture.isSuccess()).thenReturn(false);
        capturedListener1.operationComplete(failedFuture);

        // ---- Second write: this is where the bug clearly shows ----
        when(ctx.writeAndFlush(any())).thenReturn(future2);

        boolean result2 = response.writeResponse(new byte[]{4, 5, 6});

        // THE BUG: result2 is false because it returns the STALE value from the
        // previous write's failure. Even though the second write's future (future2)
        // has NOT failed yet, it returns false because isSuccessSendData was set
        // to false by the first write's async failure callback.
        //
        // CORRECT BEHAVIOR: result2 should be true (or at least not reflect the
        // previous write's outcome). Each write should reset isSuccessSendData
        // before the async write, so the return value reflects the current write.
        assertTrue("writeResponse should NOT return the stale failure value from the previous write. " +
                "The second call returned false because isSuccessSendData was set to false by " +
                "the first call's async failure callback, even though the second write has not failed yet. " +
                "This is the race condition: isSuccessSendData is read synchronously but set asynchronously. " +
                "Each writeResponse call should reset isSuccessSendData to true before writing.",
                result2);
    }

    /**
     * Test that the first call to writeResponse does not reflect a failure that
     * happens asynchronously after the return.
     *
     * Even though the return is always true (default), this demonstrates the
     * fundamental async-read-before-write problem: the return value is decided
     * before the async operation completes.
     */
    @Test
    public void testWriteResponseFirstCallReturnsBeforeAsyncCompletion() throws Exception {
        ChannelHandlerContext ctx = mock(ChannelHandlerContext.class);
        Channel channel = mock(Channel.class);
        when(ctx.channel()).thenReturn(channel);

        // First future — async, will fail
        ChannelFuture future1 = mock(ChannelFuture.class);
        when(future1.isSuccess()).thenReturn(true);
        when(future1.sync()).thenReturn(future1);

        when(channel.newPromise()).thenReturn(mock(ChannelPromise.class));
        when(ctx.writeAndFlush(any())).thenReturn(future1);

        DefaultHttpHeaders headers = new DefaultHttpHeaders();
        headers.set(HttpHeaderNames.CONTENT_TYPE, "application/grpc-web-text");
        FullHttpRequest request = new DefaultFullHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.POST, "/test", Unpooled.EMPTY_BUFFER, headers, DefaultHttpHeaders.EMPTY_HEADERS);

        SendGrpcWebResponse response = new SendGrpcWebResponse(ctx, request);

        // Call writeResponse — returns immediately, before async write completes
        boolean result = response.writeResponse(new byte[]{1, 2, 3});

        // The method returns true (default), but the async write hasn't completed yet.
        // This means we have no way of knowing if the write failed.
        // The return value is meaningless — it's just the default.

        // Now fire the failure asynchronously
        ArgumentCaptor<ChannelFutureListener> captor = ArgumentCaptor.forClass(ChannelFutureListener.class);
        verify(future1).addListener(captor.capture());

        ChannelFuture failedFuture = mock(ChannelFuture.class);
        when(failedFuture.isSuccess()).thenReturn(false);
        captor.getValue().operationComplete(failedFuture);

        // The failure happened AFTER the return. The caller already got "true"
        // and thinks the write was fine. This is the core of the race condition.
        // There's no way to assert this from the caller's perspective after the fact,
        // but the test above (testWriteResponseDoesNotReturnStalePreviousFailure)
        // demonstrates the consequence.
        assertTrue("First call returns true (default) before async completion — " +
                "this itself is a problem since we can't know the result yet", result);
    }
}

