package com.taobao.arthas.core.shell.system.impl;

import com.taobao.arthas.core.GlobalOptions;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Method;
import java.util.concurrent.TimeUnit;

import static org.junit.Assert.assertEquals;

/**
 * Test that getJobTimeoutInSecond() handles empty/whitespace jobTimeout config
 * without throwing StringIndexOutOfBoundsException internally.
 */
public class GlobalJobControllerImplEmptyTimeoutTest {

    private String originalJobTimeout;

    @Before
    public void setUp() {
        originalJobTimeout = GlobalOptions.jobTimeout;
        // Reset the exception counter before each test
        GlobalJobControllerImpl.timeoutParseExceptionCount.set(0);
    }

    @After
    public void tearDown() {
        // Restore original value
        GlobalOptions.jobTimeout = originalJobTimeout;
    }

    @Test
    public void testGetJobTimeoutInSecondWithAllWhitespaceShouldNotThrowInternalException() throws Exception {
        // Set jobTimeout to all whitespace - after trim() it becomes empty string ""
        GlobalOptions.jobTimeout = "   ";

        GlobalJobControllerImpl controller = new GlobalJobControllerImpl();

        // Use reflection to call the private method
        Method method = GlobalJobControllerImpl.class.getDeclaredMethod("getJobTimeoutInSecond");
        method.setAccessible(true);

        long result = (Long) method.invoke(controller);

        // The method should return the default value (1 day in seconds) when config is invalid
        long expectedDefault = TimeUnit.DAYS.toSeconds(1);
        assertEquals("Should return default 1 day timeout", expectedDefault, result);

        // The key assertion: no internal exception should be thrown
        // If the bug exists, charAt(-1) on empty string throws StringIndexOutOfBoundsException,
        // which is caught and increments the counter. Correct code checks for empty first
        // and never throws an exception.
        int exceptionCount = GlobalJobControllerImpl.timeoutParseExceptionCount.get();
        assertEquals("Should NOT throw StringIndexOutOfBoundsException internally when jobTimeout is empty after trim",
                0, exceptionCount);
    }
}

