package com.taobao.arthas.mcp.server.protocol.server.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.netty.channel.Channel;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelPromise;
import io.netty.handler.codec.http.DefaultFullHttpRequest;
import io.netty.handler.codec.http.FullHttpRequest;
import io.netty.handler.codec.http.FullHttpResponse;
import io.netty.handler.codec.http.HttpMethod;
import io.netty.handler.codec.http.HttpResponseStatus;
import io.netty.handler.codec.http.HttpVersion;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Tests that the handler correctly matches the MCP endpoint path,
 * rejecting URIs that merely end with the endpoint string but are
 * different paths (e.g. "/evil/mcp" must NOT match endpoint "/mcp").
 */
class McpStreamableHttpRequestHandlerPathMatchTest {

    /**
     * Subclass to expose the protected handle() method for testing.
     */
    private static class TestableHandler extends McpStreamableHttpRequestHandler {
        protected TestableHandler(ObjectMapper objectMapper, String mcpEndpoint,
                                  boolean disallowDelete) {
            super(objectMapper, mcpEndpoint, disallowDelete,
                    (req, ctx) -> ctx, null);
        }

        public void handlePublic(ChannelHandlerContext ctx, FullHttpRequest request) throws Exception {
            handle(ctx, request);
        }
    }

    @Test
    void shouldRejectUriThatEndsWithEndpointButIsDifferentPath() throws Exception {
        // mcpEndpoint is "/mcp". A URI like "/evil/mcp" ends with "/mcp"
        // but it is NOT the "/mcp" endpoint. The handler must return 404.
        McpStreamableHttpRequestHandler handler = new TestableHandler(
                new ObjectMapper(), "/mcp", false);

        // Mock ChannelHandlerContext
        ChannelHandlerContext ctx = mock(ChannelHandlerContext.class);
        Channel channel = mock(Channel.class);
        ChannelPromise promise = mock(ChannelPromise.class);
        when(ctx.channel()).thenReturn(channel);
        when(ctx.writeAndFlush(org.mockito.ArgumentMatchers.any()))
                .thenReturn(promise);
        when(channel.newPromise()).thenReturn(promise);

        // Create a GET request with URI "/evil/mcp" — this should be REJECTED
        // with 404 because it is not the "/mcp" endpoint.
        FullHttpRequest request = new DefaultFullHttpRequest(
                HttpVersion.HTTP_1_1, HttpMethod.GET, "/evil/mcp");

        ((TestableHandler) handler).handlePublic(ctx, request);

        // The correct behavior: sendError should be called with NOT_FOUND
        // because "/evil/mcp" is not the "/mcp" endpoint.
        // With the bug (endsWith check), "/evil/mcp".endsWith("/mcp") is true,
        // so it would skip the 404 and proceed to handleGetRequest, returning
        // a different error (e.g. BAD_REQUEST) instead.
        verify(ctx).writeAndFlush(org.mockito.ArgumentMatchers.argThat(
                (FullHttpResponse resp) -> resp.getStatus().equals(HttpResponseStatus.NOT_FOUND)));
    }

    @Test
    void shouldAcceptCorrectEndpointPath() throws Exception {
        // The real "/mcp" endpoint should be accepted (not return 404 at the URI check)
        McpStreamableHttpRequestHandler handler = new TestableHandler(
                new ObjectMapper(), "/mcp", false);

        ChannelHandlerContext ctx = mock(ChannelHandlerContext.class);
        Channel channel = mock(Channel.class);
        ChannelPromise promise = mock(ChannelPromise.class);
        when(ctx.channel()).thenReturn(channel);
        when(ctx.writeAndFlush(org.mockito.ArgumentMatchers.any()))
                .thenReturn(promise);
        when(channel.newPromise()).thenReturn(promise);

        // This is the correct endpoint — it should pass the URI check
        // and proceed (will fail later due to missing session headers, but NOT with 404 endpoint-not-found)
        FullHttpRequest request = new DefaultFullHttpRequest(
                HttpVersion.HTTP_1_1, HttpMethod.GET, "/mcp");

        ((TestableHandler) handler).handlePublic(ctx, request);

        // For the correct endpoint "/mcp", the response should NOT be 404 (endpoint not found).
        // It will be 400 BAD_REQUEST because no session ID header, but the key is:
        // it should NOT be 404 "Endpoint not found".
        verify(ctx).writeAndFlush(org.mockito.ArgumentMatchers.argThat(
                (FullHttpResponse resp) -> !resp.getStatus().equals(HttpResponseStatus.NOT_FOUND)));
    }

    @Test
    void shouldRejectUriWithQueryParamsThatEndsWithEndpoint() throws Exception {
        // "/foo/mcp?query=1" endsWith "/mcp" is false, but "/foo/mcp" endsWith "/mcp" is true
        McpStreamableHttpRequestHandler handler = new TestableHandler(
                new ObjectMapper(), "/mcp", false);

        ChannelHandlerContext ctx = mock(ChannelHandlerContext.class);
        Channel channel = mock(Channel.class);
        ChannelPromise promise = mock(ChannelPromise.class);
        when(ctx.channel()).thenReturn(channel);
        when(ctx.writeAndFlush(org.mockito.ArgumentMatchers.any()))
                .thenReturn(promise);
        when(channel.newPromise()).thenReturn(promise);

        // URI "/api/v1/mcp" ends with "/mcp" — should be rejected as NOT_FOUND
        FullHttpRequest request = new DefaultFullHttpRequest(
                HttpVersion.HTTP_1_1, HttpMethod.GET, "/api/v1/mcp");

        ((TestableHandler) handler).handlePublic(ctx, request);

        verify(ctx).writeAndFlush(org.mockito.ArgumentMatchers.argThat(
                (FullHttpResponse resp) -> resp.getStatus().equals(HttpResponseStatus.NOT_FOUND)));
    }
}

