package com.taobao.arthas.core.advisor;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

import org.assertj.core.api.Assertions;
import org.junit.BeforeClass;
import org.junit.Test;
import org.mockito.Mockito;

import com.taobao.arthas.core.server.ArthasBootstrap;

public class AdviceListenerManagerTest {

    @BeforeClass
    public static void setupBootstrap() throws Exception {
        // AdviceListenerManager's static initializer calls ArthasBootstrap.getInstance().
        // We must set the singleton so it does not throw IllegalStateException.
        ArthasBootstrap mock = Mockito.mock(ArthasBootstrap.class);
        ScheduledExecutorService executor = new ScheduledThreadPoolExecutor(1);
        Mockito.when(mock.getScheduledExecutorService()).thenReturn(executor);

        Field field = ArthasBootstrap.class.getDeclaredField("arthasBootstrap");
        field.setAccessible(true);
        field.set(null, mock);
    }

    private void clearAdviceListenerMap() throws Exception {
        Field mapField = AdviceListenerManager.class.getDeclaredField("adviceListenerMap");
        mapField.setAccessible(true);
        @SuppressWarnings("unchecked")
        java.util.Map<ClassLoader, AdviceListenerManager.ClassLoaderAdviceListenerManager> map =
                (java.util.Map<ClassLoader, AdviceListenerManager.ClassLoaderAdviceListenerManager>) mapField.get(null);
        map.clear();
    }

    /**
     * Verify that concurrent calls to registerAdviceListener do not lose listeners
     * due to the check-then-act race on manager creation.
     */
    @Test
    public void concurrentRegisterAdviceListenerShouldNotLoseListeners() throws Exception {
        // Run many iterations to increase chance of hitting the race window.
        AtomicBoolean lostListener = new AtomicBoolean(false);
        for (int iteration = 0; iteration < 200 && !lostListener.get(); iteration++) {
            clearAdviceListenerMap();

            ClassLoader classLoader = new ClassLoader() {};
            String className = "demo.MathGame";
            String methodName = "primeFactors";
            String methodDesc = "(I)Ljava/util/List;";

            int threadCount = 8;
            CountDownLatch startLatch = new CountDownLatch(1);
            CountDownLatch doneLatch = new CountDownLatch(threadCount);

            Thread[] threads = new Thread[threadCount];
