    /**
     * Test that the static maps in GrpcDispatcher are thread-safe.
     * HashMap is not thread-safe; concurrent put/get can cause data loss or exceptions.
     * The correct implementation should use ConcurrentHashMap.
     */
    @Test
    public void testGrpcDispatcherMapThreadSafety() throws InterruptedException {
        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.grpcInvokeMap.clear();
        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.requestParseFromMap.clear();
        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.requestToByteArrayMap.clear();
        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.responseParseFromMap.clear();
        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.responseToByteArrayMap.clear();
        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.grpcInvokeTypeMap.clear();

        int threadCount = 20;
        int entriesPerThread = 100;
        int totalExpected = threadCount * entriesPerThread;

        CountDownLatch startLatch = new CountDownLatch(1);
        CountDownLatch doneLatch = new CountDownLatch(threadCount);
        AtomicInteger exceptions = new AtomicInteger(0);

        for (int i = 0; i < threadCount; i++) {
            final int threadId = i;
            threadPool.submit(() -> {
                try {
                    startLatch.await();
                    for (int j = 0; j < entriesPerThread; j++) {
                        String key = "service" + threadId + ".method" + j;
                        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.grpcInvokeMap.put(key, null);
                        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.requestParseFromMap.put(key, null);
                        com.taobao.arthas.grpc.server.handler.GrpcDispatcher.grpcInvokeTypeMap.put(key, null);
                    }
                } catch (Throwable t) {
                    exceptions.incrementAndGet();
                    t.printStackTrace();
                } finally {
                    doneLatch.countDown();
                }
            });
        }

        startLatch.countDown();
        doneLatch.await(30, TimeUnit.SECONDS);

        int actualSize = com.taobao.arthas.grpc.server.handler.GrpcDispatcher.grpcInvokeMap.size();
        Assert.assertEquals("Concurrent HashMap writes caused data loss: expected " + totalExpected + " entries but got " + actualSize,
                totalExpected, actualSize);
    }
}

