package com.taobao.arthas.mcp.server.protocol.server.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.taobao.arthas.mcp.server.protocol.config.McpServerProperties.ServerProtocol;
import com.taobao.arthas.mcp.server.protocol.server.McpTransportContextExtractor;
import io.netty.channel.Channel;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelPromise;
import io.netty.handler.codec.http.FullHttpRequest;
import io.netty.handler.codec.http.FullHttpResponse;
import io.netty.handler.codec.http.HttpResponseStatus;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

class McpHttpRequestHandlerTest {

    @Test
    void shouldRejectRequestWithPrefixThatEndsWithEndpoint() throws Exception {
        // mcpEndpoint is "/mcp" — a URI like "/anything/mcp" should NOT match
        // because the correct behavior is exact path match, not suffix match.
        String mcpEndpoint = "/mcp";
        String craftedUri = "/anything/mcp";

        McpHttpRequestHandler handler = new McpHttpRequestHandler(
                mcpEndpoint,
                new ObjectMapper(),
                (McpTransportContextExtractor<FullHttpRequest>) (request, ctx) -> ctx
        );
        handler.setProtocol(ServerProtocol.STREAMABLE);

        // No streamableHandler set — but it shouldn't matter, since the endpoint
        // check should reject the request before getting to that point.

        FullHttpRequest request = mock(FullHttpRequest.class);
        when(request.uri()).thenReturn(craftedUri);

        ChannelHandlerContext ctx = mock(ChannelHandlerContext.class);
        Channel channel = mock(Channel.class);
        ChannelPromise promise = mock(ChannelPromise.class);
        when(ctx.channel()).thenReturn(channel);
        when(channel.newPromise()).thenReturn(promise);
        when(ctx.writeAndFlush(any())).thenAnswer(invocation -> {
            Object msg = invocation.getArgument(0);
            // Capture the FullHttpResponse that was written
            if (msg instanceof FullHttpResponse) {
                FullHttpResponse response = (FullHttpResponse) msg;
                assertThat(response.status()).isEqualTo(HttpResponseStatus.NOT_FOUND);
            }
            return mock(ChannelFuture.class);
        });

        handler.handle(ctx, request);
    }

    @Test
    void shouldAcceptRequestWithExactEndpointMatch() throws Exception {
        // The exact endpoint "/mcp" should match mcpEndpoint "/mcp"
        String mcpEndpoint = "/mcp";

        McpHttpRequestHandler handler = new McpHttpRequestHandler(
                mcpEndpoint,
                new ObjectMapper(),
                (McpTransportContextExtractor<FullHttpRequest>) (request, ctx) -> ctx
        );
        handler.setProtocol(ServerProtocol.STREAMABLE);

        // No streamableHandler set — the code will proceed past the endpoint check
        // and hit the "Streamable transport handler not available" path.

        FullHttpRequest request = mock(FullHttpRequest.class);
        when(request.uri()).thenReturn(mcpEndpoint);

        ChannelHandlerContext ctx = mock(ChannelHandlerContext.class);
        Channel channel = mock(Channel.class);
        ChannelPromise promise = mock(ChannelPromise.class);
        when(ctx.channel()).thenReturn(channel);
        when(channel.newPromise()).thenReturn(promise);
        when(ctx.writeAndFlush(any())).thenAnswer(invocation -> {
            Object msg = invocation.getArgument(0);
            if (msg instanceof FullHttpResponse) {
                FullHttpResponse response = (FullHttpResponse) msg;
                // Should get 503 (handler not available), NOT 404 (endpoint not found)
                assertThat(response.status()).isEqualTo(HttpResponseStatus.SERVICE_UNAVAILABLE);
            }
            return mock(ChannelFuture.class);
        });

        handler.handle(ctx, request);
    }
}

