package com.taobao.arthas.core.shell.term.impl.http;

import com.alibaba.deps.org.objectweb.asm.ClassReader;
import com.alibaba.deps.org.objectweb.asm.Opcodes;
import com.alibaba.deps.org.objectweb.asm.tree.AbstractInsnNode;
import com.alibaba.deps.org.objectweb.asm.tree.ClassNode;
import com.alibaba.deps.org.objectweb.asm.tree.IntInsnNode;
import com.alibaba.deps.org.objectweb.asm.tree.MethodInsnNode;
import com.alibaba.deps.org.objectweb.asm.tree.MethodNode;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.util.Iterator;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Test that verifies readFileFromResource does not use the buggy for-loop pattern
 * that initializes the read length to 0, causing writeBytes(tmp, 0, 0) on first iteration.
 *
 * The buggy pattern: for (int l = 0; l != -1; l = in.read(tmp))
 * The correct pattern: for (int l; (l = in.read(tmp)) != -1;)
 *
 * This test analyzes the bytecode of HttpRequestHandler to detect the buggy pattern.
 */
class HttpRequestHandlerReadLoopTest {

    @Test
    void readFileFromResourceShouldNotHaveBuggyLoopPattern() throws Exception {
        // Load the compiled class bytes for HttpRequestHandler
        String className = "com/taobao/arthas/core/shell/term/impl/http/HttpRequestHandler";
        try (InputStream is = getClass().getClassLoader().getResourceAsStream(className + ".class")) {
            assertThat(is).as("HttpRequestHandler class should be on classpath").isNotNull();

            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[4096];
            int n;
            while ((n = is.read(buf)) > 0) {
                baos.write(buf, 0, n);
            }
            byte[] classBytes = baos.toByteArray();

            // Parse class file using ASM tree API
            ClassNode classNode = new ClassNode();
            ClassReader classReader = new ClassReader(classBytes);
            classReader.accept(classNode, 0);

            // Find the readFileFromResource method
            MethodNode readFileFromResource = null;
            for (MethodNode method : classNode.methods) {
                if ("readFileFromResource".equals(method.name)) {
                    readFileFromResource = method;
                    break;
                }
            }

            assertThat(readFileFromResource).as("readFileFromResource method should exist").isNotNull();

            // Analyze the bytecode for the buggy pattern
            boolean buggy = detectBuggyLoopPattern(readFileFromResource);

            assertThat(buggy)
                .as("readFileFromResource should NOT use buggy loop pattern: "
                        + "for (int l = 0; l != -1; l = in.read(tmp)). "
                        + "Correct pattern is: for (int l; (l = in.read(tmp)) != -1;)")
                .isFalse();
        }
    }

    /**
     * Detect if the readFileFromResource method uses the buggy loop pattern.
     *
     * The buggy pattern: for (int l = 0; l != -1; l = in.read(tmp)) {
     *     fullResp.content().writeBytes(tmp, 0, l);
     * }
     *
     * In bytecode, this manifests as:
     * 1. ICONST_0 (push 0) - initializes local variable l to 0
     * 2. GOTO to loop check
     * 3. Loop check: load l, load -1, if_acmpne/if_icmpeq to skip loop
     * 4. Loop body: invoke writeBytes(tmp, 0, l)
     * 5. Loop increment: invoke in.read(tmp), store to l
     * 6. GOTO loop check
     *
     * We detect this by finding: ICONST_0 followed by a branch, then writeBytes call.
     */
    private boolean detectBuggyLoopPattern(MethodNode methodNode) {
        if (methodNode.instructions == null) {
            return false;
        }

        // Walk through the instruction list using getNext()
        AbstractInsnNode cursor = methodNode.instructions.getFirst();
        while (cursor != null) {
            // Look for ICONST_0 (pushing 0)
            if (cursor.getOpcode() == Opcodes.ICONST_0) {
                AbstractInsnNode next = cursor.getNext();
                if (next != null && next.getOpcode() == Opcodes.ISTORE) {
                    // Found: ICONST_0 -> ISTORE (initializing local variable to 0)
                    // Now check if this is followed by a loop structure with writeBytes
                    return checkForBuggyLoopAfterIstore(methodNode, cursor);
                }
            }
            cursor = cursor.getNext();
        }
        return false;
    }

    private void dumpInstructions(MethodNode methodNode) {
        AbstractInsnNode cursor = methodNode.instructions.getFirst();
        int i = 0;
        while (cursor != null) {
            System.out.println(i + ": " + cursor.getClass().getSimpleName() + " opcode=" + cursor.getOpcode());
            if (cursor instanceof MethodInsnNode) {
                MethodInsnNode min = (MethodInsnNode) cursor;
                System.out.println("    owner=" + min.owner + " name=" + min.name + " desc=" + min.desc);
            } else if (cursor instanceof IntInsnNode) {
                IntInsnNode iin = (IntInsnNode) cursor;
                System.out.println("    operand=" + iin.operand);
            }
            cursor = cursor.getNext();
            i++;
        }
    }

    /**
     * After finding ICONST_0 -> ISTORE, check if the rest of the method
     * contains a loop with writeBytes and in.read pattern consistent with the bug.
     */
    private boolean checkForBuggyLoopAfterIstore(MethodNode methodNode, AbstractInsnNode istoreNode) {
        // In the buggy bytecode:
        // ICONST_0; ISTORE l;  (init l = 0)
        // ... loop check: ILOAD l; ICONST_M1 (or BIPUSH -1); IF_ICMPNE skip;  (l != -1)
        // ... loop body: ... INVOKEVIRTUAL writeBytes(tmp, 0, l);
        // ... loop increment: ... INVOKEVIRTUAL in.read(tmp); ISTORE l;
        // ... GOTO loop check

        // Check if there's an ILOAD after the ISTORE that loads this same variable,
        // followed by ICONST_M1 or BIPUSH -1 for the comparison
        AbstractInsnNode cursor = istoreNode.getNext();
        while (cursor != null) {
            if (cursor.getOpcode() == Opcodes.ILOAD) {
                // Found ILOAD - this could be loading l for the loop check
                if (cursor.getNext() != null) {
                    AbstractInsnNode next = cursor.getNext();
                    if (next.getOpcode() == Opcodes.ICONST_M1) {
                        // Found ILOAD -> ICONST_M1, this is the loop check l != -1
                        return containsWriteBytesInLoop(methodNode);
                    }
                    if (next.getOpcode() == Opcodes.BIPUSH) {
                        IntInsnNode bipush = (IntInsnNode) next;
                        if (bipush.operand == -1) {
                            return containsWriteBytesInLoop(methodNode);
                        }
                    }
                }
            }
            cursor = cursor.getNext();
        }
        return false;
    }

    /**
     * Check if the method contains a writeBytes call (the loop body of the buggy pattern).
     */
    private boolean containsWriteBytesInLoop(MethodNode methodNode) {
        Iterator<AbstractInsnNode> iter = methodNode.instructions.iterator();
        while (iter.hasNext()) {
            AbstractInsnNode node = iter.next();
            if (node instanceof MethodInsnNode) {
                MethodInsnNode min = (MethodInsnNode) node;
                if ("writeBytes".equals(min.name)) {
                    return true;
                }
            }
        }
        return false;
    }
}

