package com.taobao.arthas.grpc.server.utils;

import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import org.junit.Assert;
import org.junit.Test;

/**
 * Test for ByteUtil.getBytes() to verify it returns only readable bytes,
 * not the entire underlying array.
 */
public class ByteUtilTest {

    /**
     * Unpooled.wrappedBuffer wraps a portion of a larger backing array.
     * hasArray() returns true, but array() returns the FULL underlying array.
     * getBytes() should return only the readable portion.
     */
    @Test
    public void testGetBytesReturnsOnlyReadablePortion() {
        // Create a large backing array with garbage data
        byte[] backingArray = new byte[16];
        for (int i = 0; i < backingArray.length; i++) {
            backingArray[i] = (byte) (i * 10);
        }
        // Wrap only bytes [5..7] (values 50, 60, 70) — 3 readable bytes
        ByteBuf buf = Unpooled.wrappedBuffer(backingArray, 5, 3);

        try {
            // This buffer IS backed by an array
            Assert.assertTrue("Buffer should have an underlying array", buf.hasArray());

            // Only 3 bytes are readable
            Assert.assertEquals(3, buf.readableBytes());

            // But the underlying array is the full 16-byte array
            Assert.assertEquals(16, buf.array().length);

            // getBytes() should return only the 3 readable bytes,
            // NOT the entire 16-byte backing array
            byte[] result = ByteUtil.getBytes(buf);

            Assert.assertEquals("getBytes() should return only readable bytes, not entire array",
                    3, result.length);

            // And the content should be the 3 readable bytes: [50, 60, 70]
            Assert.assertEquals((byte) 50, result[0]);
            Assert.assertEquals((byte) 60, result[1]);
            Assert.assertEquals((byte) 70, result[2]);
        } finally {
            buf.release();
        }
    }

    /**
     * When reader index is advanced past initial data, getBytes() should
     * return only bytes from readerIndex onward, not from the start of the array.
     */
    @Test
    public void testGetBytesRespectsReaderIndex() {
        // Create a buffer wrapping all of an array
        byte[] data = new byte[]{1, 2, 3, 4, 5, 6, 7, 8};
        ByteBuf buf = Unpooled.wrappedBuffer(data);

        try {
            Assert.assertTrue(buf.hasArray());

            // Advance reader index by 2, so only bytes [3..8] (6 bytes) remain readable
            buf.readerIndex(2);

            Assert.assertEquals(6, buf.readableBytes());

            byte[] result = ByteUtil.getBytes(buf);

            // Should return only the 6 readable bytes, not the full 8-byte array
            Assert.assertEquals("getBytes() should return only readable bytes from reader index",
                    6, result.length);

            // And the content should be [3, 4, 5, 6, 7, 8], starting from readerIndex
            Assert.assertEquals(3, result[0]);
            Assert.assertEquals(4, result[1]);
            Assert.assertEquals(5, result[2]);
            Assert.assertEquals(6, result[3]);
            Assert.assertEquals(7, result[4]);
            Assert.assertEquals(8, result[5]);
        } finally {
            buf.release();
        }
    }
}

