package com.taobao.arthas.grpcweb.proxy;

import io.grpc.CallOptions;
import io.grpc.Channel;
import io.grpc.ClientCall;
import io.grpc.ClientInterceptor;
import io.grpc.MethodDescriptor;
import io.grpc.Metadata;
import io.grpc.Status;
import org.junit.Test;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import static org.mockito.Mockito.*;

/**
 * Regression test for latch-countDown bug in GrpcWebClientInterceptor.
 *
 * When onHeaders() is never called on MetadataResponseListener but onClose()
 * IS called, the latch should still be counted down. Without the fix, the
 * latch remains at 1 and the caller blocks indefinitely.
 */
public class GrpcWebClientInterceptorTest {

    @Test
    public void onCloseWithoutOnHeadersShouldCountDownLatch() throws Exception {
        // Given: a latch with count 1
        CountDownLatch latch = new CountDownLatch(1);
        SendGrpcWebResponse sendResponse = mock(SendGrpcWebResponse.class);

        // When: we close the listener WITHOUT calling onHeaders first
        ClientCall.Listener<Object> listener = startCallAndGetListener(latch, sendResponse);
        listener.onClose(Status.UNAVAILABLE, new Metadata());

        // Then: the latch must be counted down (should return immediately)
        // If the bug is present, this will be false (latch never counted down)
        boolean released = latch.await(1, TimeUnit.SECONDS);
        assert released : "latch was not counted down when onClose() was called without onHeaders()";
    }

    @Test
    public void onCloseWithOnHeadersShouldCountDownLatch() throws Exception {
        // Given
        CountDownLatch latch = new CountDownLatch(1);
        SendGrpcWebResponse sendResponse = mock(SendGrpcWebResponse.class);

        ClientCall.Listener<Object> listener = startCallAndGetListener(latch, sendResponse);

        // Normal flow: onHeaders is called, then onClose
        listener.onHeaders(new Metadata());
        listener.onClose(Status.OK, new Metadata());

        boolean released = latch.await(1, TimeUnit.SECONDS);
        assert released : "latch was not counted down when onClose() was called after onHeaders()";
    }

    /**
     * Creates the interceptor, starts a call through it, and returns the
     * wrapped ClientCall.Listener that the interceptor provides.
     */
    @SuppressWarnings("unchecked")
    private ClientCall.Listener<Object> startCallAndGetListener(
            CountDownLatch latch, SendGrpcWebResponse sendResponse) {

        // Mock Channel -> mock ClientCall
        ClientCall<Object, Object> delegateCall = mock(ClientCall.class);
        Channel channel = mock(Channel.class);
        when(channel.newCall(any(MethodDescriptor.class), any(CallOptions.class)))
                .thenReturn(delegateCall);

        // Capture the listener the interceptor wraps
        ClientCall.Listener<Object>[] captured = new ClientCall.Listener[1];
        doAnswer(invocation -> {
            captured[0] = invocation.getArgument(0);
            return null;
        }).when(delegateCall).start(any(ClientCall.Listener.class), any(Metadata.class));

        // Build interceptor and intercept
        GrpcWebClientInterceptor interceptor = new GrpcWebClientInterceptor(latch, sendResponse);

        // Build a simple MethodDescriptor without protobuf
        io.grpc.MethodDescriptor.Marshaller<Object> marshaller = new io.grpc.MethodDescriptor.Marshaller<Object>() {
            @Override public java.io.InputStream stream(Object value) { return new java.io.ByteArrayInputStream(new byte[0]); }
            @Override public Object parse(java.io.InputStream stream) { return null; }
        };
        MethodDescriptor<Object, Object> method = MethodDescriptor.<Object, Object>newBuilder(marshaller, marshaller)
                .setType(MethodDescriptor.MethodType.UNARY)
                .setFullMethodName("test/service/test")
                .build();

        ClientCall<Object, Object> interceptedCall = interceptor.interceptCall(
                method, CallOptions.DEFAULT, channel);

        ClientCall.Listener<Object> testListener = mock(ClientCall.Listener.class);
        interceptedCall.start(testListener, new Metadata());

        return captured[0];
    }
}

