package com.taobao.arthas.grpc.server.handler;

import com.taobao.arthas.grpc.server.utils.ByteUtil;
import io.netty.buffer.ByteBuf;
import org.junit.Assert;
import org.junit.Test;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.zip.GZIPOutputStream;

/**
 * Unit tests for GrpcRequest decompression behavior.
 * gRPC wire format: [compression_flag (1 byte)][length (4 bytes)][payload]
 * When compression_flag is 0x01, the payload is GZIP-compressed.
 */
public class GrpcRequestDecompressionTest {

    /**
     * Test that writeData properly decompresses a GZIP-compressed gRPC message.
     * 
     * gRPC wire format for a compressed message:
     * - Byte 0: 0x01 (compressed flag)
     * - Bytes 1-4: length of the compressed payload (big-endian)
     * - Bytes 5+: GZIP-compressed payload
     * 
     * The correct behavior is that writeData should detect the compressed flag
     * and decompress the payload, storing the decompressed data in byteData.
     * 
     * The BUG: the code checks for GZIP magic bytes (0x1f 0x8b) at the start
     * of the data, but in gRPC framing, byte 0 is the compression flag (0x01),
     * not GZIP magic. So decompression never triggers.
     */
    @Test
    public void testWriteDataDecompressesCompressedGrpcMessage() throws IOException {
        // Original plain text payload
        String originalPayload = "Hello, this is the original protobuf payload data!";
        byte[] originalBytes = originalPayload.getBytes();

        // Step 1: GZIP compress the payload
        byte[] gzipCompressed = gzipCompress(originalBytes);

        // Step 2: Wrap in gRPC wire format: [0x01][4-byte length][gzip payload]
        byte[] grpcFrame = buildGrpcFrame(true, gzipCompressed);

        // Step 3: Write the gRPC frame data
        GrpcRequest request = new GrpcRequest(1, "test.Service", "TestMethod");
        ByteBuf byteBuf = ByteUtil.newByteBuf(grpcFrame);
        request.writeData(byteBuf);

        // Step 4: Read back what was stored
        byte[] storedData = ByteUtil.getBytes(request.getByteData());

        // The correct behavior: the stored data should contain the DECOMPRESSED payload.
        // i.e., byteData should contain the original plain text, not the gzip-compressed bytes.
        Assert.assertEquals("writeData should decompress gRPC-compressed data",
                originalBytes.length, storedData.length);
        Assert.assertArrayEquals("Stored data should match original payload after decompression",
                originalBytes, storedData);
    }

    /**
     * Test that uncompressed gRPC messages pass through without change.
     * gRPC wire format: [0x00][4-byte length][plain payload]
     */
    @Test
    public void testWriteDataPassesThroughUncompressedGrpcMessage() throws IOException {
        // Original plain text payload
        String originalPayload = "Hello, uncompressed data";
        byte[] originalBytes = originalPayload.getBytes();

        // Wrap in gRPC wire format: [0x00][4-byte length][plain payload]
        byte[] grpcFrame = buildGrpcFrame(false, originalBytes);

        GrpcRequest request = new GrpcRequest(1, "test.Service", "TestMethod");
        ByteBuf byteBuf = ByteUtil.newByteBuf(grpcFrame);
        request.writeData(byteBuf);

        byte[] storedData = ByteUtil.getBytes(request.getByteData());

        // For uncompressed data, the stored data should contain the full gRPC frame
        // (compression flag + length + payload) since no decompression is needed.
        // Actually, the correct behavior depends on the design. Let's just verify
        // the data is stored.
        Assert.assertNotNull("Data should be stored", storedData);
        Assert.assertTrue("Data should not be empty", storedData.length > 0);
    }

    /**
     * Test that GZIP-compressed data is correctly detected and decompressed,
     * even though the first byte is the gRPC compression flag (0x01), not GZIP magic.
     */
    @Test
    public void testCompressedFlagDetected() throws IOException {
        byte[] originalBytes = "test data for compression".getBytes();
        byte[] gzipCompressed = gzipCompress(originalBytes);
        byte[] grpcFrame = buildGrpcFrame(true, gzipCompressed);

        // Verify the frame starts with 0x01 (compressed flag), NOT GZIP magic
        Assert.assertEquals("First byte should be gRPC compression flag 0x01",
                (byte) 0x01, grpcFrame[0]);
        Assert.assertNotEquals("Second byte should NOT be GZIP magic byte 0x8b",
                (byte) 0x8b, grpcFrame[1]);

        // Verify gzip magic is in the payload portion (starting at byte 5)
        Assert.assertEquals("GZIP magic byte 1 at payload start", 
                (byte) 0x1f, grpcFrame[5]);
        Assert.assertEquals("GZIP magic byte 2 at payload start", 
                (byte) 0x8b, grpcFrame[6]);

        GrpcRequest request = new GrpcRequest(1, "test.Service", "TestMethod");
        ByteBuf byteBuf = ByteUtil.newByteBuf(grpcFrame);
        request.writeData(byteBuf);

        byte[] storedData = ByteUtil.getBytes(request.getByteData());

        // The stored data should be the decompressed payload, matching original
        Assert.assertArrayEquals("Decompressed data should match original",
                originalBytes, storedData);
    }

    /**
     * Compress bytes using GZIP.
     */
    private byte[] gzipCompress(byte[] data) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (GZIPOutputStream gzos = new GZIPOutputStream(baos)) {
            gzos.write(data);
        }
        return baos.toByteArray();
    }

    /**
     * Build a gRPC wire frame: [compression_flag][4-byte big-endian length][payload].
     */
    private byte[] buildGrpcFrame(boolean compressed, byte[] payload) {
        byte[] frame = new byte[1 + 4 + payload.length];
        // Compression flag
        frame[0] = (byte) (compressed ? 0x01 : 0x00);
        // 4-byte big-endian length
        frame[1] = (byte) ((payload.length >> 24) & 0xFF);
        frame[2] = (byte) ((payload.length >> 16) & 0xFF);
        frame[3] = (byte) ((payload.length >> 8) & 0xFF);
        frame[4] = (byte) (payload.length & 0xFF);
        // Payload
        System.arraycopy(payload, 0, frame, 5, payload.length);
        return frame;
    }
}

