package com.taobao.arthas.core.command.monitor200;

import org.junit.Assert;
import org.junit.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;

public class SizeLimitValidationTest {

    @Test
    public void testWatchSizeLimitValidation() {
        Assert.assertEquals("sizeLimit must be greater than 0.", WatchCommand.validateSizeLimit(Integer.valueOf(0)));
        Assert.assertEquals("sizeLimit must be greater than 0.", WatchCommand.validateSizeLimit(Integer.valueOf(-1)));
        Assert.assertNull(WatchCommand.validateSizeLimit(Integer.valueOf(1)));
        Assert.assertNull(WatchCommand.validateSizeLimit(null));
    }

    @Test
    public void testTimeTunnelSizeLimitValidation() {
        Assert.assertEquals("sizeLimit must be greater than 0.", TimeTunnelCommand.validateSizeLimit(Integer.valueOf(0)));
        Assert.assertEquals("sizeLimit must be greater than 0.", TimeTunnelCommand.validateSizeLimit(Integer.valueOf(-1)));
        Assert.assertNull(TimeTunnelCommand.validateSizeLimit(Integer.valueOf(1)));
        Assert.assertNull(TimeTunnelCommand.validateSizeLimit(null));
    }

    @Test
    public void testMonitorAdviceListenerKeyHashCodeNoCollision() throws Exception {
        // Access the private inner class Key via reflection
        Class<?> keyClass = Class.forName("com.taobao.arthas.core.command.monitor200.MonitorAdviceListener$Key");
        Constructor<?> ctor = keyClass.getDeclaredConstructor(String.class, String.class);
        ctor.setAccessible(true);

        // Create Key("ClassA", "MethodB") and Key("ClassB", "MethodA")
        // These are NOT equal (equals checks both fields in order), but with the buggy
        // hashCode using commutative addition (a + b == b + a), they collide.
        Object key1 = ctor.newInstance("ClassA", "MethodB");
        Object key2 = ctor.newInstance("ClassB", "MethodA");

        Method equalsMethod = keyClass.getMethod("equals", Object.class);
        Method hashCodeMethod = keyClass.getMethod("hashCode");

        // Verify they are NOT equal (equals is correct)
        Assert.assertFalse("Key(ClassA, MethodB) should not equal Key(ClassB, MethodA)",
                (Boolean) equalsMethod.invoke(key1, key2));

        // The buggy hashCode uses className.hashCode() + methodName.hashCode()
        // which is commutative, so Key(A,B) and Key(B,A) produce the same hash.
        // A correct hashCode should differentiate these distinct keys.
        int hash1 = (Integer) hashCodeMethod.invoke(key1);
        int hash2 = (Integer) hashCodeMethod.invoke(key2);

        Assert.assertNotEquals(
                "Distinct keys Key(A,B) and Key(B,A) must have different hash codes " +
                "(commutative addition in hashCode causes collisions degrading ConcurrentHashMap performance)",
                hash1, hash2);
    }
}

